import fs from "node:fs";
import path from "node:path";

export const MIGRATION_RE = /^\d{4}_[a-z0-9_]+\.sql$/;

export function listMigrations(dir) {
  return fs.readdirSync(dir).filter((f) => MIGRATION_RE.test(f)).sort();
}

/** One paste-able file containing every migration, plus the bookkeeping rows `npm run migrate` expects. */
export function buildSetupSql(dir) {
  const files = listMigrations(dir);
  const parts = [
    "-- Repair Bench: complete database setup.",
    "-- GENERATED by `npm run build:sql` from supabase/migrations. Do not edit by hand.",
    "-- Paste this whole file into the Supabase SQL Editor and press Run, on a new empty project only.",
    "",
  ];
  for (const f of files) parts.push(`-- ===== ${f} =====`, fs.readFileSync(path.join(dir, f), "utf8").trim(), "");
  parts.push(
    "-- ===== migration bookkeeping =====",
    "create table if not exists public.schema_migrations (name text primary key, applied_at timestamptz not null default now());",
    "alter table public.schema_migrations enable row level security;",
    `insert into public.schema_migrations (name) values\n${files.map((f) => `  ('${f}')`).join(",\n")}\non conflict do nothing;`,
    ""
  );
  return parts.join("\n");
}
